import Foundation

// The fixture must be generated by the current Rust source-bound command:
// cargo iroha-fast -- run -p kotlin-fixture-gen --features dev-tools -- identifier-owner-execute-v1
// Save stdout as fixtures/soracloud/identifier_owner_execute_v1.json. No synthetic positive DATA.
func currentOwnerExecuteFixture() throws -> [String: Any] {
    let root = URL(fileURLWithPath: #filePath)
        .deletingLastPathComponent().deletingLastPathComponent()
        .deletingLastPathComponent().deletingLastPathComponent()
    let url = root.appendingPathComponent("fixtures/soracloud/identifier_owner_execute_v1.json")
    let data = try Data(contentsOf: url)
    guard let fixture = try JSONSerialization.jsonObject(with: data) as? [String: Any],
          fixture["schema"] as? String == "iroha.identifier.owner-execute.v1",
          fixture["classification"] as? String == "PUBLIC_SOFTWARE_DATA_UNADMITTED",
          fixture["response"] is [String: Any] else {
        throw NSError(domain: "NativeOwnerExecuteDATA", code: 1,
                      userInfo: [NSLocalizedDescriptionKey: "Missing current genuine Rust execute DATA fixture."])
    }
    return fixture
}

func currentOwnerExecuteResponseField(_ key: String) throws -> String {
    let fixture = try currentOwnerExecuteFixture()
    guard let response = fixture["response"] as? [String: Any], let value = response[key] as? String else {
        throw NSError(domain: "NativeOwnerExecuteDATA", code: 2,
                      userInfo: [NSLocalizedDescriptionKey: "Missing original execute DATA field: \(key)"])
    }
    return value
}

func ramLfeExecuteResponseJSON(
    programId: String? = nil,
    opaqueHash: String? = nil,
    receiptHash: String? = nil,
    opaqueOutputHex: String? = nil,
    outputHash: String? = nil,
    associatedDataHash: String? = nil,
    backend: String? = nil,
    verificationMode: String? = nil
) throws -> Data {
    let fixture = try currentOwnerExecuteFixture()
    var response = fixture["response"] as! [String: Any]
    let changes: [(String, String?)] = [
        ("program_id", programId), ("opaque_hash", opaqueHash), ("receipt_hash", receiptHash),
        ("opaque_output", opaqueOutputHex), ("output_hash", outputHash),
        ("associated_data_hash", associatedDataHash), ("backend", backend),
        ("verification_mode", verificationMode)
    ]
    for (key, value) in changes { if let value { response[key] = value } }
    return try JSONSerialization.data(withJSONObject: response, options: [.sortedKeys])
}

func ramLfeReceiptVerifyResponseJSON(
    programId: String = "identifier_lookup_retail",
    backend: String = "bfv-programmed-v1",
    verificationMode: String = "signed",
    outputHash: String = String(repeating: "44", count: 32),
    associatedDataHash: String = String(repeating: "55", count: 32)
) -> Data {
    """
    {
      "valid":true,
      "program_id":"\(programId)",
      "backend":"\(backend)",
      "verification_mode":"\(verificationMode)",
      "output_hash":"\(outputHash)",
      "associated_data_hash":"\(associatedDataHash)",
      "output_hash_matches":true
    }
    """.data(using: .utf8)!
}
